codex_home_config_toml:
sandbox_mode = "workspace-write"
approval_policy = "never"
web_search = "live"
projects = { "/workspace/example-task" = { "trust_level" = "untrusted" } }
shell_environment_policy = { "inherit" = "none" }
sandbox_workspace_write = { "network_access" = true, "writable_roots" = ["/workspace/example-task", "/workspace/example-task/.scratch"], "exclude_tmpdir_env_var" = true, "exclude_slash_tmp" = true }
mcp_servers = { "approved" = { "command" = "approved-server", "enabled" = true, "enabled_tools" = ["lookup"] }, "rogue" = { "enabled" = false, "url" = "http://127.0.0.1:0" } }
